// n8n Code node in "Run Once for Each Item" mode. Monetary math uses integer microdollars.
const { project, budgetUsd, usdPerSecond, shots } = $json;
const issues = [];
const rows = [];
const seen = new Set();

function microdollars(value) {
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) return null;
  const match = /^(\d+)(?:\.(\d{1,6}))?$/.exec(String(value));
  if (!match) return null;
  const units = Number(match[1]) * 1000000 + Number((match[2] || '').padEnd(6, '0'));
  return Number.isSafeInteger(units) ? units : null;
}

const cap = microdollars(budgetUsd);
if (typeof project !== 'string' || !project.trim()) issues.push('Enter a project or batch name.');
if (cap === null) issues.push('Enter a non-negative numeric USD budget with at most six decimal places.');
if (!Array.isArray(shots) || !shots.length) issues.push('Add at least one shot.');
const rates = new Map();
for (const preset of ['768P', '2K']) {
  const rate = microdollars(usdPerSecond?.[preset]);
  if (rate !== null && rate > 0) rates.set(preset, rate);
}

let firstPass = 0;
let fullBatch = 0;
for (const [i, shot] of (Array.isArray(shots) ? shots : []).entries()) {
  const label = 'Row ' + (i + 1);
  const id = typeof shot?.shotId === 'string' ? shot.shotId.trim() : '';
  const preset = typeof shot?.preset === 'string' ? shot.preset.trim().toUpperCase() : '';
  const rate = rates.get(preset);
  const seconds = shot?.seconds;
  const takes = shot?.maxTakes;
  const before = issues.length;
  if (!id) issues.push(label + ': enter a shot ID.');
  else if (seen.has(id.toUpperCase())) issues.push(label + ': duplicate shot ID ' + id + '.');
  if (id) seen.add(id.toUpperCase());
  if (!rate) issues.push(label + ': use 768P or 2K and set a positive USD rate for it.');
  if (!Number.isInteger(seconds) || seconds < 4 || seconds > 15) issues.push(label + ': seconds must be an integer from 4 to 15.');
  if (!Number.isSafeInteger(takes) || takes < 1) issues.push(label + ': maxTakes must count the first take and be a positive integer.');
  if (issues.length !== before) continue;
  const one = rate * seconds;
  const all = one * takes;
  if (!Number.isSafeInteger(firstPass + one) || !Number.isSafeInteger(fullBatch + all)) {
    issues.push(label + ': the amount is too large to calculate precisely.');
    continue;
  }
  firstPass += one;
  fullBatch += all;
  rows.push({project, shotId:id, preset, seconds, maxTakes:takes, firstTakeUsd:one/1000000, estimatedMaxUsd:all/1000000});
}
if (issues.length) return {json:{project, status:'invalid_input', issues}};
return {json:{
  project, status: fullBatch <= cap ? 'within_budget' : 'over_budget',
  shotCount:rows.length, budgetUsd, firstPassUsd:firstPass/1000000,
  retakeAllowanceUsd:(fullBatch-firstPass)/1000000, estimatedMaxUsd:fullBatch/1000000,
  remainingUsd:(cap-fullBatch)/1000000, shots:rows
}};
